import decimal
from decimal import ROUND_HALF_UP

def round_price(x: float) -> float:
    """Round a price to cents using half-up rounding."""
    # Convert to Decimal and round to 2 decimal places using ROUND_HALF_UP
    return float(decimal.Decimal(x).quantize(decimal.Decimal('0.00'), rounding=ROUND_HALF_UP))

